using Microsoft.EntityFrameworkCore;
class MigrationRunner
{
    // Breaking Change #3: EF Core 9 no longer allows calling Migrate() inside
    // a manual transaction. Migrations manage their own transactions internally.
    void ApplyMigrations(AppDbContext db)
    {
        var strategy = db.Database.CreateExecutionStrategy();
        strategy.Execute(() =>
        {
            db.Database.Migrate();
        });
    }

    // For Cosmos: use async APIs (sync is deprecated in EF Core 9 Cosmos provider)
    async Task QueryProductsAsync(CosmosDbContext cosmosDb)
    {
        var products = await cosmosDb.Products.ToListAsync();
    }
}

